using namespace std;

int main() {
    long long n, u;
    if (scanf("%lld %lld", &n, &u) != 2) return 0;
    long long last = -1, answer = 0, v;  // last = weight of the last kept vehicle (-1: none)
    for (long long i = 0; i < n && scanf("%lld", &v) == 1; i++) {
        if (v > u) answer++;
        else if (last < 0 || last + v <= u) last = v;
        else { answer++; last = min(last, v); }  // drop the heavier of the conflicting pair
