import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        DataInputStream in = new DataInputStream(new BufferedInputStream(System.in, 1 << 16));
        long n = readLong(in), u = readLong(in);
        long last = -1, answer = 0; // last = weight of the last kept vehicle (-1: none)
        for (long i = 0; i < n; i++) {
            long v = readLong(in);
            if (v > u) answer++;
            else if (last < 0 || last + v <= u) last = v;
            else { answer++; last = Math.min(last, v); } // drop the heavier of the conflicting pair
        }
        System.out.println(answer);
    }

    static long readLong(DataInputStream in) throws IOException {
        int b = in.read();
        while (b != '-' && (b < '0' || b > '9')) b = in.read();
        boolean neg = false;
        if (b == '-') { neg = true; b = in.read(); }
        long r = 0;
        while (b >= '0' && b <= '9') { r = r * 10 + (b - '0'); b = in.read(); }
        return neg ? -r : r;
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

func readInt(in *bufio.Reader) int64 {
	b, _ := in.ReadByte()
	for b != '-' && (b < '0' || b > '9') {
		b, _ = in.ReadByte()
	}
	neg := false
	if b == '-' {
		neg = true
		b, _ = in.ReadByte()
	}
	var r int64
	for b >= '0' && b <= '9' {
		r = r*10 + int64(b-'0')
		b, _ = in.ReadByte()
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<16)
	n, u := readInt(in), readInt(in)
	last, answer := int64(-1), int64(0) // last = weight of the last kept vehicle (-1: none)
	for i := int64(0); i < n; i++ {
		v := readInt(in)
		if v > u {
			answer++
		} else if last < 0 || last+v <= u {
			last = v
		} else {
			answer++
			last = min(last, v) // drop the heavier of the conflicting pair
		}
	}
	fmt.Println(answer)
}
